    #[test]
    fn committed_header_scenes_parse() {
        // every committed card scene may declare `Header` chrome; verify a
        // representative set (title + glyph + live meta) parses and that the
        // `Header` item carries the expected fields. This test used to hold
        // the HYBRID stubs — the ones whose body was still a resident `Ink`;
        // accent (2026-10-06) was the last of them and now asserts the OTHER
        // way. The 2026-09-17 Batch 2 conversions
        // (journaltail/systemdunits/smarthealth/thermal/conninfo) plus the
        // 2026-09-24 gauge cards (cpu/mem — see
        // `committed_cpu_mem_scenes_parse_zero_ink`), the 2026-09-25
        // compositor card and the battery cards (see
        // `battery_scenes_parse_zero_ink`) are fully declarative and moved to
        // the zero-Ink assertions below. water + eyerest likewise left this
        // list once `gauge_water_eyerest_scenes_parse_zero_ink` took them over;
        // disk + gpu (2026-09-27) left it for `disk_gpu_scenes_parse_zero_ink`
        // (cpugpu joined them in 2026-09-27 and left for Lua in 2026-10-10),
        // speedtest and micmeter left it for `speedtest_scene_is_zero_ink`
        // and `micmeter_scene_is_zero_ink`; branding left it for
        // `branding_scene_is_zero_ink`; workspaces left it for
        // `the_workspaces_tiles_land_on_the_drawer_geometry`; pomodoro (retired
        // with the Lua module) for `pomodoro_scene_is_zero_ink`; audiodevice (same
        // session) for `audiodevice_scene_is_zero_ink`; powerdraw (2026-09-27g,
        // two `Spark` traces over the drawer's own plot box) for
        // `the_powerdraw_scene_matches_its_own_drawer`; moon (2026-09-27l, a
        // `Moon` terminator-disc primitive over one per-frame phase sample) for
        // `moon_scene_is_zero_ink`; wallpaper (same session — a bound tile grid plus
        // its scrollbar, the whole card's geometry riding the shell's own fit
        // arithmetic) for `wallpaper_scene_is_zero_ink`; worldclock (same
        // session — the pinned clock, the city list, the `+` row, and the search
        // plate with its keyed match rows, the match list itself a pure function
        // of the zones and the buffer) for `worldclock_scene_is_zero_ink` and
        // `the_worldclock_scene_matches_its_own_drawer`; accent for
        // `the_accent_picker_scene_matches_its_own_drawer` +
        // `the_accent_subview_scene_matches_its_own_drawer`.
        for id in ["accent"] {
            let path = crate::vars::card_scene_path(id);
            if !path.exists() {
                continue;
            }
            let s = std::fs::read_to_string(&path).expect("scene file readable");
            let scene: CardScene = parse_scene_ron(&s)
                .unwrap_or_else(|e| panic!("committed {id}.ron must parse: {e}"));
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Header { .. })),
                "{id} scene declares Header chrome"
            );
            assert!(
                !scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ink { .. })),
                "{id} scene is fully declarative — its last `Ink` body (the \
                 custom-accents subview) moved into the scene with the picker"
            );
            assert_eq!(
                scene
                    .items
                    .iter()
                    .filter(|i| matches!(i, SceneItem::Rows { .. }))
                    .count(),
                2,
                "{id} scene draws both of its lists — the three sources and the paged accents"
            );
        }
    }

    #[test]
    fn committed_batch2_body_scenes_parse_zero_ink() {
        // journaltail / systemdunits / smarthealth (severity rows + refresh
        // Hit), thermal (fixed-height chip Grid), conninfo (metric rows +
        // refresh Hit) — Header-led, zero-Ink, data-driven via a live body
        // (Rows/Grid) and the centered empty-state caption.
        for id in [
            "journaltail",
            "systemdunits",
            "smarthealth",
            "thermal",
            "conninfo",
        ] {
            let path = crate::vars::card_scene_path(id);
            if !path.exists() {
                continue;
            }
            let s = std::fs::read_to_string(&path).expect("scene file readable");
            let scene: CardScene = parse_scene_ron(&s)
                .unwrap_or_else(|e| panic!("committed {id}.ron must parse: {e}"));
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Header { .. })),
                "{id} scene declares Header chrome"
            );
            assert!(
                !scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ink { .. })),
                "{id} scene is fully declarative (no Ink body)"
            );
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Rows { .. } | SceneItem::Grid { .. })),
                "{id} scene is data-driven via Rows/Grid"
            );
            assert!(
                scene.items.iter().any(|i| matches!(
                    i,
                    SceneItem::Text {
                        center_x: true,
                        center_y: true,
                        visible: Some(_),
                        ..
                    }
                )),
                "{id} scene gates a centered empty-state caption"
            );
        }
        // the four refreshed data cards carry their bottom-right refresh Hit
        // at the resident handler's key
        for (id, key) in [
            ("journaltail", crate::shell::JOURNAL_REFRESH_KEY),
            ("systemdunits", crate::shell::SYSTEMD_REFRESH_KEY),
            ("smarthealth", crate::shell::SMART_REFRESH_KEY),
            ("conninfo", crate::shell::CONNINFO_REFRESH_KEY),
        ] {
            let path = crate::vars::card_scene_path(id);
            if !path.exists() {
                continue;
            }
            let s = std::fs::read_to_string(&path).expect("scene file readable");
            let scene: CardScene = parse_scene_ron(&s).unwrap();
            assert!(
                scene.items.iter().any(
                    |i| matches!(i, SceneItem::Hit { key: k, .. } if *k == Val::Lit(key as f32))
                ),
                "{id} scene carries the refresh Hit (key {key})"
            );
        }
        // thermal's chip grid is FIXED-height (no stretch — Rust parity)
        let path = crate::vars::card_scene_path("thermal");
        if path.exists() {
            let s = std::fs::read_to_string(&path).expect("scene file readable");
            let scene: CardScene = parse_scene_ron(&s).unwrap();
            let grid = scene
                .items
                .iter()
                .find_map(|i| match i {
                    SceneItem::Grid { cell_h, cols, .. } => Some((*cell_h, *cols)),
                    _ => None,
                })
                .expect("thermal scene declares the chip Grid");
            assert_eq!(
                grid,
                (24.0, 3),
                "thermal grid: 3 cols, fixed 24 px chip rows"
            );
        }
    }

    #[test]
    fn committed_cpu_mem_scenes_parse_zero_ink() {
        // cpu / mem (2026-09-24) — Header-led gauge cards, fully declarative
        // (no Ink body): a bead-ring `Ring` + data-driven `Rows` (metric
        // rows), and mem additionally carries the bottom swap `Bar` gated by
        // a presence toggle. The Rust drawers are now dead for these ids.
        for id in ["cpu", "mem"] {
            let path = crate::vars::card_scene_path(id);
            if !path.exists() {
                continue;
            }
            let s = std::fs::read_to_string(&path).expect("scene file readable");
            let scene: CardScene = parse_scene_ron(&s)
                .unwrap_or_else(|e| panic!("committed {id}.ron must parse: {e}"));
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Header { .. })),
                "{id} scene declares Header chrome"
            );
            assert!(
                !scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ink { .. })),
                "{id} scene is fully declarative (no Ink body)"
            );
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ring { .. })),
                "{id} scene draws the bead-ring gauge"
            );
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Rows { .. })),
                "{id} scene is data-driven via Rows"
            );
        }
        let path = crate::vars::card_scene_path("mem");
        if path.exists() {
            let s = std::fs::read_to_string(&path).expect("scene file readable");
            let scene: CardScene = parse_scene_ron(&s).unwrap();
            let bar = scene
                .items
                .iter()
                .find_map(|i| match i {
                    SceneItem::Bar {
                        value,
                        max,
                        visible,
                        ..
                    } => Some((value.as_str(), *max, visible.clone())),
                    _ => None,
                })
                .expect("mem scene declares the swap Bar");
            assert_eq!(bar.0, "{swap_frac}", "swap bar binds the fractional value");
            assert_eq!(bar.1, 100.0, "swap bar fraction is of a 100 max");
            assert_eq!(
                bar.2.as_deref(),
                Some("swap_show"),
                "swap bar shown only in use"
            );
        }
    }

    #[test]
    fn rows_edge_text_cells_anchor_right_and_bottom_inset_clips() {
        // Batch 2 (2026-09-17): plain text cells honor `edge` (the cell's
        // RIGHT edge lands at card_w − edge — news open-glyph/ticker chg%
        // parity), and `bottom` reserves the last N px of the card (the
        // conninfo list clears its refresh button).
        let scene: CardScene = parse_scene_ron(
            r#"(items: [ Rows(name: "rw", y: 30.0, row_h: 18.0, pad: 12.0, bottom: 32.0, cols: [
                (x: 0.0),
                (x: 0.0, w: 0.0, edge: Some(14.0), right: true, font: mono, size: 8.5),
            ], key_base: Some(91)) ])"#,
        )
        .unwrap();
        let mk = |v: &str| SceneRow {
            cols: vec!["iface".into(), v.into()],
            key: 0,
            action: None,
            color: None,
            col_colors: vec![],
            surface: None,
        };
        let mut values = SceneValues::new();
        values.insert(
            "rw",
            SceneValue::Rows(vec![
                mk("10.0.0.2"),
                mk("10.0.0.3"),
                mk("10.0.0.4"),
                mk("10.0.0.5"),
                mk("10.0.0.6"),
                mk("10.0.0.7"),
            ]),
        );
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            220.0,
            140.0,
            scale(),
            &pal(),
            &values,
            0,
            true,
            true,
        );
        // right cells: text anchored at card_w − 14 = 206 (right → draws left of it)
        assert!(
            v.iter().any(|c| matches!(c, Cmd::Text { x, right: true, text, .. } if (*x - 206.0).abs() < 0.01 && text == "10.0.0.2")),
            "edge cell right-anchors at card_w − edge",
        );
        // bottom inset 32: rows start at 30, pitch 18 → row boxes crossing
        // y=108 (140−32) are skipped: rows at 30/48/66/84 fit, 102+108 do not
        assert_eq!(
            hits.len(),
            4,
            "rows past the bottom inset are skipped (got {hits:?})"
        );
        assert_eq!(hits[3].key, 94);
    }

    #[test]
    fn grid_fixed_cell_h_keeps_pitch() {
        // thermal chips: `cell_h` fixes the row pitch — a partial tail row
        // leaves the rest of the box open instead of stretching cells
        let scene: CardScene = parse_scene_ron(
            r#"(items: [ Grid(name: "g", x: 0.0, y: 0.0, h: 100.0, cols: 3, gap: 2.0, cell_h: 24.0) ])"#,
        )
        .unwrap();
        let mut values = SceneValues::new();
        let chip = |t: &str| GridCell {
            text: t.into(),
            surface: Some(ColorToken::Raised),
            ..Default::default()
        };
        values.insert(
            "g",
            SceneValue::GridCells(vec![
                chip("acpitz"),
                chip("core"),
                chip("nvme"),
                chip("acpi2"),
            ]),
        );
        let mut v: Vec<Cmd> = Vec::new();
        let _ = scene.draw(
            &mut v,
            0.0,
            0.0,
            220.0,
            140.0,
            scale(),
            &pal(),
            &values,
            0,
            true,
            true,
        );
        let chip_h: Vec<f32> = v
            .iter()
            .filter_map(|c| match c {
                // any rounded rect is a chip (the default `r` is 8 px)
                Cmd::Rect { h, r, .. } if *r > 0.0 => Some(*h),
                _ => None,
            })
            .collect();
        assert_eq!(
            chip_h.len(),
            4,
            "all four chips drawn (2 rows, partial tail) — got {chip_h:?}"
        );
        assert!(
            chip_h.iter().all(|h| (*h - 24.0).abs() < 0.01),
            "fixed 24 px chip height (got {chip_h:?})"
        );
    }

