    #[test]
    fn notes_scene_declares_the_list_and_composer_without_ink() {
        let path = crate::vars::card_scene_path("notes");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene =
            parse_scene_ron(&s).unwrap_or_else(|e| panic!("committed notes.ron must parse: {e}"));
        assert!(
            !scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Ink { .. })),
            "notes scene is fully declarative — the list, empty hint, add/save buttons and the composer are all declared"
        );
        let rows = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Rows {
                    name,
                    y,
                    row_dy,
                    start,
                    visible,
                    bottom,
                    hairline,
                    cols,
                    ..
                } = i
                {
                    Some((
                        name.clone(),
                        y.clone(),
                        *row_dy,
                        start.clone(),
                        visible.clone(),
                        *bottom,
                        *hairline,
                        cols.clone(),
                    ))
                } else {
                    None
                }
            })
            .expect("notes scene declares the note-list Rows item");
        assert_eq!(rows.0, "notes_rows");
        assert_eq!(rows.1, Val::Lit(32.0), "rows start 32 px below the header");
        assert_eq!(rows.2, 0.0, "row_dy 0 — title baseline at the row top");
        assert_eq!(
            rows.3.as_deref(),
            Some("notes_scroll"),
            "scroll binds notes_scroll"
        );
        assert_eq!(
            rows.4.as_deref(),
            Some("notes_list"),
            "the list draws only while the composer is CLOSED"
        );
        assert_eq!(
            rows.5, 32.0,
            "bottom inset is the drawer's 32 px add-button zone (`notes_card_visible`)"
        );
        assert!(rows.6, "hairline divider under every row");
        assert_eq!(rows.7.len(), 3);
        assert!(rows.7[0].icon, "bullet col is an icon glyph");
        assert_eq!(rows.7[0].size, 9.0);
        assert_eq!(rows.7[1].size, 9.5);
        assert_eq!(
            rows.7[1].max_chars,
            Some(36),
            "title column carries the drawer's 36-glyph cap"
        );
        assert_eq!(
            rows.7[2].dy,
            Some(12.0),
            "body-caption sits 12 px below the title"
        );
        assert_eq!(rows.7[2].size, 8.0);
        assert_eq!(
            rows.7[2].max_chars,
            Some(44),
            "body column carries the drawer's 44-glyph cap"
        );
        // the composer half of the card is declared too — plate + field
        // surfaces, a caret per focused field, the wrapped body as its own
        // `Rows`, and the two round `Hit` buttons
        assert!(
            scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Rows { name, .. } if name == "notes_body_lines")),
            "the wrapped body is a declared Rows item"
        );
        assert!(
            scene.items.iter().any(|i| {
                matches!(
                    i,
                    SceneItem::Hit { key, visible, .. }
                        if *key == Val::Lit(crate::shell::NOTES_KEY_INPUT as f32)
                            && visible.as_deref() == Some("notes_list")
                )
            }),
            "the add button carries NOTES_KEY_INPUT and lives on the list stage"
        );
        assert!(
            scene.items.iter().any(|i| {
                matches!(
                    i,
                    SceneItem::Hit { key, visible, .. }
                        if *key == Val::Lit(crate::shell::NOTES_KEY_SAVE as f32)
                            && visible.as_deref() == Some("notes_body_active")
                )
            }),
            "the save + carries NOTES_KEY_SAVE and only lives on the body stage"
        );
        assert!(
            scene.items.iter().any(|i| {
                matches!(
                    i,
                    SceneItem::Surface { visible, x, .. }
                        if visible.as_deref() == Some("notes_title_active")
                            && matches!(x, Val::Expr(_))
                )
            }),
            "the title caret is a declared Surface gated to the active title field, x bound to the caret measurement"
        );
    }

    #[test]
    fn rows_pill_cell_draws_chip_with_derived_fill() {
        let scene: CardScene = parse_scene_ron(
            r#"(items: [ Rows(name: "rw", y: 30.0, row_h: 24.0, row_dy: 0.0, pad: 12.0, cols: [
                (x: 0.0, truncate: Some(120.0), size: 9.5),
                (x: 0.0, edge: Some(12.0), right: true, dy: Some(6.0), size: 8.5, pill: Some((height: 16.0, radius: 8.0))),
            ]) ])"#,
        )
        .unwrap();
        let mut values = SceneValues::new();
        values.insert(
            "rw",
            SceneValue::Rows(vec![SceneRow {
                cols: vec!["aaaaaaaaaaaaaaaaaaaaaa".into(), "7d".into()],
                key: 0,
                action: None,
                color: None,
                surface: None,
                col_colors: vec![None, Some(ColorToken::Warn)],
            }]),
        );
        let mut v: Vec<Cmd> = Vec::new();
        let (_h, _i) = scene.draw(
            &mut v,
            0.0,
            0.0,
            200.0,
            120.0,
            scale(),
            &pal(),
            &values,
            0,
            true,
            true,
        );
        // truncate: label cut to fit card_w - 2·pad - 120 at 0.62·fs(9.5)
        // (56 px / 5.89 → 9 glyphs, the ≥8 floor)
        assert!(
            v.iter()
                .any(|c| matches!(c, Cmd::Text { text, .. } if text == "aaaaaaaaa")),
            "long label truncated to the reserved width",
        );
        assert!(
            !v.iter()
                .any(|c| matches!(c, Cmd::Text { text, .. } if text == "aaaaaaaaaaaaaaaaaaaaaa")),
            "untruncated label not drawn"
        );
        // chip: right edge at card_w - pad(12), auto width = 2·0.62·fs(8.5) + 2·5
        let pw = 2.0 * 0.62 * 8.5 + 10.0;
        let pl = 200.0 - 12.0 - pw;
        let hov = crate::ui::hover(&pal());
        let chip = v.iter().find_map(|c| {
            if let Cmd::Rect {
                x, w, h, r, color, ..
            } = c
            {
                if (*x - pl).abs() < 0.01 {
                    Some((*w, *h, *r, *color))
                } else {
                    None
                }
            } else {
                None
            }
        });
        let (w, h, r, color) = chip.expect("chip rect drawn at the edge anchor");
        assert!(
            (w - pw).abs() < 0.01 && h == 16.0 && r == 8.0,
            "chip auto-sized (w {w} h {h} r {r})"
        );
        assert_eq!(color, hov, "Warn chip text → hover fill");
        // Warn-glyph centered across the chip
        assert!(v.iter().any(|c| matches!(c, Cmd::Text { text, x, .. } if text == "7d" && (x - (pl + pw / 2.0)).abs() < 0.01)), "chip text centered in the pill");
        // Acc-token chip derives the acc-tint fill
        values.insert(
            "rw",
            SceneValue::Rows(vec![SceneRow {
                cols: vec!["a".into(), "today!".into()],
                key: 0,
                action: None,
                color: None,
                surface: None,
                col_colors: vec![None, Some(ColorToken::Acc)],
            }]),
        );
        let mut v: Vec<Cmd> = Vec::new();
        let (_h, _i) = scene.draw(
            &mut v,
            0.0,
            0.0,
            200.0,
            120.0,
            scale(),
            &pal(),
            &values,
            0,
            true,
            true,
        );
        let tint = mix(pal().bg, pal().acc, 0.16);
        let cube = v
            .iter()
            .any(|c| matches!(c, Cmd::Rect { color, .. } if *color == tint));
        assert!(cube, "acc chip derived acc-tint fill");
    }

    #[test]
    fn rows_pill_del_anchors_left_of_chip() {
        let scene: CardScene = parse_scene_ron(
            r#"(items: [ Rows(name: "rw", y: 30.0, row_h: 24.0, pad: 12.0, cols: [
                (x: 0.0, size: 9.5),
                (x: 0.0, edge: Some(12.0), right: true, dy: Some(6.0), size: 8.5, pill: Some(()), del_anchor: true),
            ], del_base: 70, del_pad: 20.0, del_dy: 4.0) ])"#,
        )
        .unwrap();
        let mut values = SceneValues::new();
        values.insert(
            "rw",
            SceneValue::Rows(vec![SceneRow {
                cols: vec!["Release".into(), "today!".into()],
                key: 0,
                action: None,
                color: None,
                surface: None,
                col_colors: vec![None, Some(ColorToken::Acc)],
            }]),
        );
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _i) = scene.draw(
            &mut v,
            0.0,
            0.0,
            200.0,
            120.0,
            scale(),
            &pal(),
            &values,
            70,
            true,
            true,
        );
        let pw = 6.0 * 0.62 * 8.5 + 10.0;
        let pl = 200.0 - 12.0 - pw;
        let dange = ColorToken::Danger.resolve(&pal());
        assert!(
            v.iter().any(|c| matches!(c, Cmd::Text { text, x, .. } if text == ICON_CLOSE && (x - (pl - 20.0)).abs() < 0.01)),
            "✕ anchors left of the chip at del_pad",
        );
        assert!(
            v.iter().any(|c| matches!(c, Cmd::Text { text, color, .. } if text == ICON_CLOSE && *color == dange)),
            "the revealed ✕ is danger-red (reveal-on-✕ rows)",
        );
        assert_eq!(hits.len(), 1, "only the del region registers");
        let h = &hits[0];
        assert!(
            (h.x - (pl - 22.0)).abs() < 0.01 && h.y == 30.0 && h.w == 20.0 && h.h == 24.0,
            "anchor region sits full-row left of the chip"
        );
    }

    #[test]
    fn countdown_scene_declares_rows_beside_a_declarative_composer() {
        let path = crate::vars::card_scene_path("countdown");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene = parse_scene_ron(&s)
            .unwrap_or_else(|e| panic!("committed countdown.ron must parse: {e}"));
        assert!(
            !scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Ink { .. })),
            "countdown scene is fully declarative (2026-09-27) — the header chrome and the \
             add-event composer row joined the event list"
        );
        assert!(
            scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Header { .. })),
            "the countdown header chrome is declarative"
        );
        // the composer: a fill, its buffer text, and the region's own hit
        let (surf, txt, hit) = {
            let mut s = None;
            let mut t = None;
            let mut h = None;
            for i in &scene.items {
                match i {
                    SceneItem::Surface {
                        x,
                        y,
                        w,
                        h: sh,
                        r,
                        color,
                        ..
                    } if s.is_none() => {
                        let name = match color {
                            ColorToken::Value(d) => d.as_str().to_string(),
                            other => format!("{other:?}"),
                        };
                        s = Some((x.clone(), y.clone(), w.clone(), sh.clone(), *r, name))
                    }
                    SceneItem::Text {
                        x,
                        y,
                        text,
                        font_size,
                        ..
                    } if t.is_none() => {
                        t = Some((x.clone(), y.clone(), text.clone(), font_size.clone()))
                    }
                    SceneItem::Hit {
                        x,
                        y,
                        w,
                        h: hh,
                        key,
                        ..
                    } if h.is_none() => {
                        h = Some((x.clone(), y.clone(), w.clone(), hh.clone(), key.clone()))
                    }
                    _ => {}
                }
            }
            (s, t, h)
        };
        assert_eq!(
            surf,
            Some((
                Val::Lit(12.0),
                Val::Lit(26.0),
                Val::Lit(-12.0),
                Val::Lit(22.0),
                6.0,
                "countdown_input_bg".to_string()
            )),
            "composer fill"
        );
        assert_eq!(
            txt,
            Some((
                Val::Lit(20.0),
                Val::Lit(31.0),
                "{countdown_shown}".to_string(),
                Val::Lit(8.5)
            )),
            "buffer text"
        );
        assert_eq!(
            hit,
            Some((
                Val::Lit(12.0),
                Val::Lit(26.0),
                Val::Lit(-12.0),
                Val::Lit(24.0),
                Val::Lit(crate::shell::COUNTDOWN_INPUT_KEY as f32)
            )),
            "the click region the keyboard path listens on"
        );
        let rows = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Rows {
                    name,
                    y,
                    del_base,
                    del_pad,
                    del_dy,
                    cols,
                    ..
                } = i
                {
                    Some((
                        name.clone(),
                        y.clone(),
                        *del_base,
                        *del_pad,
                        *del_dy,
                        cols.clone(),
                    ))
                } else {
                    None
                }
            })
            .expect("countdown scene declares the event-list Rows item");
        assert_eq!(rows.0, "countdown_rows");
        assert_eq!(rows.1, Val::Lit(50.0), "rows start below the composer row");
        assert_eq!(rows.2, crate::shell::COUNTDOWN_DEL_BASE, "del base matches");
        assert_eq!(rows.3, 20.0, "✕ gap left of the chip");
        assert_eq!(rows.4, 4.0, "✕ baseline inside the row");
        assert_eq!(rows.5.len(), 3);
        assert_eq!(rows.5[0].dy, Some(3.0), "label baseline");
        assert_eq!(
            rows.5[0].truncate,
            Some(120.0),
            "label reserves the chip zone"
        );
        assert_eq!(rows.5[1].dy, Some(13.0), "date caption baseline");
        assert_eq!(rows.5[1].color, Some(ColorToken::Fg3));
        assert_eq!(
            rows.5[2].edge,
            Some(12.0),
            "chip right edge at the card pad"
        );
        assert!(rows.5[2].right, "chip right-anchored");
        assert_eq!(
            rows.5[2].pill,
            Some(PillSpec {
                bg: None,
                height: 16.0,
                radius: 8.0,
                pad: 5.0,
                top: 3.0
            })
        );
        assert!(rows.5[2].del_anchor, "del anchors left of the chip");
    }

    /// Values helper for the countdown card's declarative chrome: the header
    /// meta (upcoming count), the composer buffer (placeholder hint while
    /// empty) and the two bound inks (the fill lifts on focus, the placeholder
    /// hint is dim until something is typed).
    fn countdown_vals(buf: &str, focus: bool, upcoming: usize) -> SceneValues {
        let mut m = SceneValues::new();
        m.insert(
            "countdown_meta",
            SceneValue::Text(format!("{upcoming} upcoming")),
        );
        m.insert(
            "countdown_shown",
            SceneValue::Text(if buf.is_empty() {
                "add event — name 2026-12-31".to_string()
            } else {
                buf.to_string()
            }),
        );
        m.insert_color(
            "countdown_shown_ink",
            SceneColor::Token(if buf.is_empty() {
                ColorToken::Fg3
            } else {
                ColorToken::Fg
            }),
        );
        m.insert_color(
            "countdown_input_bg",
            SceneColor::Token(if focus {
                ColorToken::HoverHl
            } else {
                ColorToken::Hover
            }),
        );
        m
    }

    #[test]
    fn the_countdown_composer_lands_on_the_drawer_geometry() {
        // 260x120 card: the drawer paints its fill at (12, 26, 236, 22) r6,
        // the buffer 8 px in / 5 px down at 8.5 px, and registers a click box
        // one row-height tall (24) — 2 px taller than the fill it frames.
        let (v, hits) = gau_draw("countdown", 260.0, 120.0, &countdown_vals("", false, 2));
        assert_eq!(
            rects(&v),
            vec![(12.0, 26.0, 236.0, 22.0, crate::ui::hover(&pal()))],
            "the composer fill is the card's only rect"
        );
        let t = texts(&v);
        let buf = t
            .iter()
            .find(|(_, _, _, s)| s.contains("add event"))
            .expect("buffer drawn");
        assert_eq!(
            (buf.0, buf.1, buf.2),
            (20.0, 31.0, 8.5),
            "8 px in, 5 px down"
        );
        let meta = t
            .iter()
            .find(|(_, _, _, s)| s == "2 upcoming")
            .expect("header meta drawn");
        assert_eq!(
            (meta.0, meta.1),
            (248.0, 11.0),
            "right-anchored on the header rail"
        );
        // the region is the fill's box, two pixels taller
        let h = hits
            .iter()
            .find(|h| h.key == crate::shell::COUNTDOWN_INPUT_KEY)
            .expect("composer region");
        assert_eq!((h.x, h.y, h.w, h.h), (12.0, 26.0, 236.0, 24.0));
    }

    #[test]
    fn the_countdown_composer_follows_its_focus_and_buffer() {
        // focused + empty → lifted fill, dim placeholder hint
        let (v, _) = gau_draw("countdown", 260.0, 120.0, &countdown_vals("", true, 0));
        assert_eq!(
            rects(&v),
            vec![(12.0, 26.0, 236.0, 22.0, crate::ui::hover_hl(&pal()))],
            "the fill lifts while the row has focus"
        );
        assert_eq!(
            texts(&v)
                .iter()
                .find(|(_, _, _, s)| s.contains("add event"))
                .map(|t| t.3.as_str()),
            Some("add event — name 2026-12-31"),
            "the placeholder still shows"
        );
        // typed + unfocused → resting fill, full-fg buffer
        let (v, _) = gau_draw(
            "countdown",
            260.0,
            120.0,
            &countdown_vals("Trip 2030-05-05", false, 1),
        );
        assert_eq!(
            rects(&v),
            vec![(12.0, 26.0, 236.0, 22.0, crate::ui::hover(&pal()))]
        );
        let t = texts(&v);
        assert!(
            t.iter().any(|(_, _, _, s)| s == "Trip 2030-05-05"),
            "the buffer replaces the hint, got {:?}",
            t.iter().map(|t| t.3.as_str()).collect::<Vec<_>>()
        );
        assert!(
            !t.iter().any(|(_, _, _, s)| s.contains("add event")),
            "the hint is gone"
        );
    }

    /// Values helper for the workspaces card: one cell per workspace, the
    /// active one carrying the drawer's accent wash (bound per frame, so the
    /// tile is a straight 16% alpha accent), its accent ink and its pip.
    fn ws_vals(n: usize, active: usize) -> SceneValues {
        let mut m = SceneValues::new();
        let p = pal();
        m.insert(
            "ws_meta",
            SceneValue::Text(format!("{}/{n}", (active + 1).min(n))),
        );
        m.insert_color("ws_fill_act", SceneColor::Raw((p.acc & 0xFFFF_FF00) | 0x28));
        m.insert(
            "ws_tiles",
            SceneValue::GridCells(
                (0..n)
                    .map(|i| {
                        let on = i == active;
                        let fill = if on {
                            ColorToken::Value(DynColor::new("ws_fill_act").unwrap())
                        } else {
                            ColorToken::Hover
                        };
                        GridCell {
                            text: (i + 1).to_string(),
                            surface: Some(fill),
                            surface_hover: if on { Some(fill) } else { None },
                            color: if on { Some(ColorToken::Acc) } else { None },
                            marker: if on { Some(ColorToken::Acc) } else { None },
                            vcenter: true,
                            ..GridCell::default()
                        }
                    })
                    .collect(),
            ),
        );
        m
    }

    #[test]
    fn workspaces_scene_is_zero_ink() {
        let scene = batt_scene("workspaces").expect("scene present");
        assert!(
            !scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Ink { .. })),
            "the tile grid is the whole body — the Rust drawer is only the fallback"
        );
        assert!(
            scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Header { .. })),
            "the header chrome is declarative"
        );
        let g = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Grid {
                    name,
                    cols_break,
                    cell_max_w,
                    cell_max_h,
                    center,
                    cell_w_break,
                    key_base,
                    ..
                } = i
                {
                    Some((
                        name.clone(),
                        cols_break.clone(),
                        *cell_max_w,
                        *cell_max_h,
                        *center,
                        cell_w_break.clone(),
                        *key_base,
                    ))
                } else {
                    None
                }
            })
            .expect("the tile grid is a Grid item");
        assert_eq!(g.0, "ws_tiles");
        // the drawer's `(w − 24) / 34` ladder, written out: tile k needs a card
        // of `24 + 34·k` px, up to the 10-column clamp
        assert_eq!(g.1.first(), Some(&(58.0, 1)), "one tile from 58 px wide");
        assert_eq!(g.1.last(), Some(&(364.0, 10)), "the 10-tile clamp ceiling");
        assert_eq!(g.2, 48.0, "tile width cap");
        assert_eq!(g.3, 40.0, "tile height cap");
        assert!(g.4, "the capped block centers in the body");
        assert_eq!(
            g.5,
            vec![(30.0, 11.0)],
            "the 30 px label-size ladder (9 px is the base)"
        );
        assert_eq!(
            g.6,
            crate::shell::WORKSPACE_KEY_BASE,
            "the click ladder matches the drawer"
        );
    }

    #[test]
    fn the_workspaces_tiles_land_on_the_drawer_geometry() {
        // 220x110 card, 6 workspaces, the third active. The drawer's ladder
        // gives 5 columns → two rows of 34.4 x 34 tiles; the block exactly
        // fills the body, so the grid starts flush at (12, 30).
        let (v, hits) = gau_draw("workspaces", 220.0, 110.0, &ws_vals(6, 2));
        let rs = rects(&v);
        let tiles: Vec<_> = rs.iter().copied().filter(|r| r.2 != 3.0).collect();
        assert_eq!(tiles.len(), 6, "one fill per workspace");
        assert_eq!(
            tiles[0],
            (12.0, 30.0, 34.4, 34.0, crate::ui::hover(&pal())),
            "first tile"
        );
        assert_eq!(
            tiles[2],
            (92.8, 30.0, 34.4, 34.0, (pal().acc & 0xFFFF_FF00) | 0x28),
            "the active tile's accent wash"
        );
        assert_eq!(
            tiles[5],
            (12.0, 70.0, 34.4, 34.0, crate::ui::hover(&pal())),
            "second row wraps under the first"
        );
        // the active pip: 3 px square, 6 px above the tile's bottom edge
        assert_eq!(
            rs.iter().copied().find(|r| r.2 == 3.0),
            Some((108.5, 58.0, 3.0, 3.0, pal().acc)),
            "the pip rides the active tile's bottom center"
        );
        // the label rides the tile's midpoint by its own font height (11 px
        // here: a 34 px tile clears the 30 px ladder step)
        let t = texts(&v);
        let l1 = t
            .iter()
            .find(|(_, _, _, s)| s == "1")
            .expect("tile 1 numbered");
        assert_eq!(
            (l1.0, l1.1, l1.2),
            (29.2, 40.5, 11.0),
            "centered on the tile, 1 px optical bias"
        );
        let l3 = t
            .iter()
            .find(|(_, _, _, s)| s == "3")
            .expect("tile 3 numbered");
        assert_eq!(
            (l3.0, l3.1),
            (110.0, 40.5),
            "the active tile's number is centered too"
        );
        // one region per tile, on the drawer's key ladder
        let keys: Vec<u32> = hits.iter().map(|h| h.key).collect();
        assert_eq!(
            keys,
            (0..6)
                .map(|i| crate::shell::WORKSPACE_KEY_BASE + i)
                .collect::<Vec<_>>()
        );
        let h0 = &hits[0];
        assert_eq!(
            (h0.x, h0.y, h0.w, h0.h),
            (12.0, 30.0, 34.4, 34.0),
            "the region is the tile box"
        );
    }

    #[test]
    fn the_workspace_column_ladder_follows_the_card_width() {
        // 300x160, 10 workspaces: the ladder reaches 8 columns, which makes a
        // tile 29.25 wide — under the 30 px step, so the labels drop to 9 px
        let (v, hits) = gau_draw("workspaces", 300.0, 160.0, &ws_vals(10, 0));
        let tiles: Vec<_> = rects(&v).iter().copied().filter(|r| r.2 != 3.0).collect();
        assert_eq!(tiles.len(), 10);
        assert_eq!(
            tiles[0],
            (12.0, 49.0, 29.25, 40.0, (pal().acc & 0xFFFF_FF00) | 0x28),
            "8 columns, vertically centered"
        );
        assert_eq!(
            tiles[7],
            (258.75, 49.0, 29.25, 40.0, crate::ui::hover(&pal())),
            "the eighth column ends the row"
        );
        assert_eq!(
            tiles[8],
            (12.0, 95.0, 29.25, 40.0, crate::ui::hover(&pal())),
            "the second row wraps under the first"
        );
        assert_eq!(
            tiles[9],
            (47.25, 95.0, 29.25, 40.0, crate::ui::hover(&pal())),
            "and keeps the column pitch"
        );
        let nine = texts(&v)
            .into_iter()
            .find(|t| t.3 == "9")
            .expect("tile 9 numbered");
        assert_eq!(nine.2, 9.0, "a 29.25 px tile takes the small label");
        assert_eq!(
            nine.1, 109.5,
            "and it re-centers on its own font height (row 1)"
        );
        assert_eq!(hits.len(), 10, "every tile still registers");
        // the count cap: 3 workspaces in a card wide enough for 8 stay 3 wide
        // tiles (the drawer's `.min(n)`) — the block centers in the body
        let (v2, hits2) = gau_draw("workspaces", 220.0, 110.0, &ws_vals(3, 0));
        let t2: Vec<_> = rects(&v2).iter().copied().filter(|r| r.2 != 3.0).collect();
        assert_eq!(t2.len(), 3);
        assert_eq!(
            t2[0],
            (32.0, 47.0, 48.0, 40.0, (pal().acc & 0xFFFF_FF00) | 0x28),
            "3 tiles, 48 wide, centered"
        );
        assert_eq!(t2[2], (140.0, 47.0, 48.0, 40.0, crate::ui::hover(&pal())));
        assert_eq!(hits2.len(), 3, "and only three regions");
    }

    #[test]
    fn the_active_workspace_keeps_its_wash_under_the_cursor() {
        // the drawer tests `active` BEFORE hover, so pointing at the active
        // tile leaves the accent wash (not the strong hover fill) in place
        let scene = batt_scene("workspaces").expect("scene present");
        let mut v: Vec<Cmd> = Vec::new();
        let vals = ws_vals(3, 1);
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            220.0,
            110.0,
            scale(),
            &pal(),
            &vals,
            crate::shell::WORKSPACE_KEY_BASE + 1,
            true,
            true,
        );
        let act = (pal().acc & 0xFFFF_FF00) | 0x28;
        let hovered_active = rects(&v).into_iter().find(|r| r.4 == act);
        assert_eq!(
            hovered_active.map(|r| r.0),
            Some(86.0),
            "the middle (active) tile keeps its wash"
        );
        assert_eq!(
            hits.iter()
                .find(|h| h.key == crate::shell::WORKSPACE_KEY_BASE + 1)
                .map(|h| h.x),
            Some(86.0),
            "and it is the tile the cursor is actually over"
        );
        // a resting tile under the cursor takes the strong hover fill
        let scene = batt_scene("workspaces").expect("scene present");
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            220.0,
            110.0,
            scale(),
            &pal(),
            &ws_vals(3, 1),
            crate::shell::WORKSPACE_KEY_BASE,
            true,
            true,
        );
        assert!(
            rects(&v)
                .iter()
                .any(|r| r.4 == crate::ui::hover_hl(&pal()) && r.0 == 32.0),
            "the resting tile under the cursor lifts"
        );
        assert_eq!(hits.len(), 3);
    }

    #[test]
    fn quote_scene_declares_textwrap_without_ink() {
        let path = crate::vars::card_scene_path("quote");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene =
            parse_scene_ron(&s).unwrap_or_else(|e| panic!("committed quote.ron must parse: {e}"));
        assert!(
            !scene.items.iter().any(|i| matches!(i, SceneItem::Ink { .. })),
            "quote scene is fully declarative (2026-09-27) — the pills, header and meta are declared too"
        );
        let tw = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::TextWrap {
                    text,
                    caption,
                    top,
                    bottom,
                    visible,
                    ..
                } = i
                {
                    Some((
                        text.clone(),
                        caption.clone(),
                        *top,
                        *bottom,
                        visible.clone(),
                    ))
                } else {
                    None
                }
            })
            .expect("quote scene declares the TextWrap body");
        assert!(
            tw.0.contains("quote_text"),
            "text interpolates the body value"
        );
        assert_eq!(
            tw.1,
            Some("— {quote_author}".into()),
            "caption carries the author line"
        );
        assert_eq!(tw.2, 28.0, "box top clears the header");
        assert_eq!(
            tw.3, 40.0,
            "box bottom is the drawer's own 40 px reserve under the pill row"
        );
        assert_eq!(
            tw.4,
            Some("quote_has".into()),
            "visible gate bound to quote_has"
        );
    }

    #[test]
    fn textwrap_wraps_at_thirty_four_and_centers() {
        // 136 chars (4 lines of 34) + author caption
        let long_text = "abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789";
        let scene: CardScene = parse_scene_ron(
            "(items: [ TextWrap(text: \"{tw_text}\", caption: Some(\"— {tw_author}\"), top: 28.0, bottom: 36.0, visible: Some(\"tw_has\")) ])"
        )
        .unwrap();
        let mut vals = SceneValues::new();
        vals.insert("tw_text", SceneValue::Text(long_text.to_string()));
        vals.insert("tw_author", SceneValue::Text("Ada Lovelace".into()));
        vals.insert("tw_has", SceneValue::Toggle(true));
        let mut v: Vec<Cmd> = Vec::new();
        let (_h, _i) = scene.draw(
            &mut v,
            0.0,
            0.0,
            200.0,
            100.0,
            scale(),
            &pal(),
            &vals,
            0,
            true,
            true,
        );
        let text_cmds: Vec<_> = v.iter().filter(|c| matches!(c, Cmd::Text { .. })).collect();
        assert_eq!(text_cmds.len(), 5, "4 wrapped lines + 1 author caption");
        // visible=false suppresses everything
        let mut v2: Vec<Cmd> = Vec::new();
        vals.insert("tw_has", SceneValue::Toggle(false));
        scene.draw(
            &mut v2,
            0.0,
            0.0,
            200.0,
            100.0,
            scale(),
            &pal(),
            &vals,
            0,
            true,
            true,
        );
        assert!(
            v2.iter().all(|c| !matches!(c, Cmd::Text { .. })),
            "visible=false skips draw"
        );
    }

    #[test]
    fn expenses_scene_is_fully_declarative() {
        let path = crate::vars::card_scene_path("expenses");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene = parse_scene_ron(&s)
            .unwrap_or_else(|e| panic!("committed expenses.ron must parse: {e}"));
        assert!(
            scene
                .items
                .iter()
                .all(|i| !matches!(i, SceneItem::Ink { .. })),
            "fully declarative — no Ink painters remain"
        );
        let hdr = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Header {
                    title,
                    meta,
                    meta_mono,
                    meta_color,
                    ..
                } = i
                {
                    Some((title.clone(), meta.clone(), *meta_mono, *meta_color))
                } else {
                    None
                }
            })
            .expect("header declares the MTD meta");
        assert_eq!(hdr.0, "Expenses");
        assert!(hdr.1.as_deref().unwrap_or_default().contains("exp_meta"));
        assert!(hdr.2, "MTD total is mono");
        assert_eq!(hdr.3, Some(ColorToken::Acc), "MTD total in accent ink");
        let rows: Vec<&SceneItem> = scene
            .items
            .iter()
            .filter(|i| matches!(i, SceneItem::Row { .. }))
            .collect();
        assert_eq!(rows.len(), 2, "chips row + composer row");
        let hits_in = |row: &SceneItem| -> Vec<(Val, Val, String)> {
            match row {
                SceneItem::Row { items, .. } => items
                    .iter()
                    .filter_map(|c| {
                        if let SceneItem::Hit { key, w, text, .. } = c {
                            Some((key.clone(), w.clone(), text.clone()))
                        } else {
                            None
                        }
                    })
                    .collect(),
                _ => vec![],
            }
        };
        let chips = hits_in(rows[0]);
        assert_eq!(
            chips.iter().map(|(k, _, _)| k.clone()).collect::<Vec<_>>(),
            vec![
                Val::Lit(31800.0),
                Val::Lit(31801.0),
                Val::Lit(31802.0),
                Val::Lit(31803.0),
                Val::Lit(31804.0),
                Val::Lit(31805.0)
            ],
            "chip keys mirror EXPENSE_CHIP_BASE..+5"
        );
        assert!(
            chips.iter().all(|(_, w, _)| *w == Val::Lit(0.0)),
            "chips equal-split the row"
        );
        assert_eq!(
            chips.iter().map(|(_, _, t)| t.as_str()).collect::<Vec<_>>(),
            vec!["1", "5", "10", "20", "50", "100"],
            "preset amounts 1..=100"
        );
        let comp = scene
            .items
            .iter()
            .flat_map(|i| {
                if let SceneItem::Row { items, .. } = i {
                    items.iter().collect::<Vec<_>>()
                } else {
                    vec![]
                }
            })
            .find_map(|c| {
                if let SceneItem::Composer {
                    pad,
                    text,
                    focus,
                    key,
                    ..
                } = c
                {
                    Some((*pad, text.clone(), focus.clone(), *key))
                } else {
                    None
                }
            })
            .expect("composer declared");
        assert_eq!(
            comp.0, 0.0,
            "row pad supplies the inset — no double padding"
        );
        assert_eq!(comp.1, Some("{exp_buf}".into()));
        assert_eq!(comp.2, Some("exp_focus".into()));
        assert_eq!(comp.3, crate::shell::EXPENSE_INPUT_KEY);
        let _clear = hits_in(rows[1]);
        let clr_hit = scene
            .items
            .iter()
            .flat_map(|i| {
                if let SceneItem::Row { items, .. } = i {
                    items.iter().collect::<Vec<_>>()
                } else {
                    vec![]
                }
            })
            .find_map(|c| {
                if let SceneItem::Hit {
                    key,
                    w,
                    color,
                    color_hover,
                    ..
                } = c
                {
                    if *key == Val::Lit(crate::shell::EXPENSE_CLEAR_KEY as f32) {
                        Some((key.clone(), w.clone(), *color, *color_hover))
                    } else {
                        None
                    }
                } else {
                    None
                }
            });
        let c = clr_hit.expect("clear hit declared");
        assert_eq!(
            c.1,
            Val::Lit(70.0),
            "clear-month fixed 70 next to the composer"
        );
        assert_eq!(c.2, Some(ColorToken::Fg2));
        assert_eq!(
            c.3,
            Some(ColorToken::Danger),
            "clear label flips danger on hover"
        );
        let bars: Vec<_> = scene
            .items
            .iter()
            .filter_map(|i| {
                if let SceneItem::Bar {
                    reserve, visible, ..
                } = i
                {
                    Some((*reserve, visible.clone()))
                } else {
                    None
                }
            })
            .collect();
        assert_eq!(bars.len(), 3, "top-3 per-category bars");
        assert!(
            bars.iter().all(|(r, v)| *r == 46.0 && v.is_some()),
            "bars reserve the amount column and gate by category"
        );
        let empty = scene
            .items
            .iter()
            .find(|i| matches!(i, SceneItem::Text { visible, .. } if visible.as_deref() == Some("exp_empty")))
            .expect("empty-month caption gated by exp_empty");
        let _ = empty;
    }

    #[test]
    fn expense_primitives_reserve_gate_and_hover() {
        let mut vals = SceneValues::new();
        vals.insert("cat1", SceneValue::Text("food".into()));
        vals.insert("amt1", SceneValue::Text("42".into()));
        vals.insert("ratio1", SceneValue::Text("0.5".into()));
        vals.insert("has1", SceneValue::Toggle(true));
        vals.insert("empty", SceneValue::Toggle(false));
        let scene: CardScene = parse_scene_ron(
            "(items: [
                Header(title: \"Expenses\", meta: Some(\"{meta}\"), meta_mono: true, meta_color: Some(acc)),
                Text(x: 12.0, y: 90.0, text: \"{cat1}\", font_size: 8.0, visible: Some(\"has1\")),
                Bar(x: 12.0, y: 101.0, w: 0.0, h: 4.0, value: \"{ratio1}\", reserve: 46.0, visible: Some(\"has1\")),
                Text(x: 12.0, y: 96.0, center_x: true, text: \"nothing logged this month\", font_size: 8.5, visible: Some(\"empty\")),
                Hit(x: 0.0, y: 200.0, w: 70.0, h: 22.0, text: \"clear mo\", color: Some(fg2), color_hover: Some(danger), key: 31_811),
             ])",
        )
        .unwrap();
        let mut hvals = vals.clone();
        hvals.insert("meta", SceneValue::Text("MTD 42".into()));
        let mut v: Vec<Cmd> = Vec::new();
        scene.draw(
            &mut v,
            0.0,
            0.0,
            300.0,
            120.0,
            scale(),
            &pal(),
            &hvals,
            31_811,
            true,
            true,
        );
        // header meta — accent mono
        let acc = ColorToken::Acc.resolve(&pal());
        assert!(
            v.iter().any(
                |c| matches!(c, Cmd::Text { text, color, .. } if text == "MTD 42" && *color == acc)
            ),
            "meta color accent + mono still substituted"
        );
        // bar reserve → 300 − 46 track
        let track: Vec<_> = v
            .iter()
            .filter_map(|c| {
                if let Cmd::Rect { x, y, w, h, .. } = c {
                    Some((*x, *y, *w, *h))
                } else {
                    None
                }
            })
            .filter(|(_, yy, _, _)| (*yy - 101.0).abs() < 0.01)
            .collect();
        assert!(
            track.iter().any(|(xx, _, ww, hh)| (*xx - 12.0).abs() < 0.01
                && (*ww - 254.0).abs() < 0.01
                && *hh == 4.0),
            "bar spans card_w − reserve"
        );
        // visible=false caption suppressed
        assert!(
            !v.iter().any(
                |c| matches!(c, Cmd::Text { text, .. } if text == "nothing logged this month")
            ),
            "empty caption hidden while a category bar exists"
        );
        // hover swaps the clear label to danger
        let dange = ColorToken::Danger.resolve(&pal());
        let found = v.iter().any(
            |c| matches!(c, Cmd::Text { text, color, .. } if text == "clear mo" && *color == dange),
        );
        assert!(found, "clear mo flips to danger while hovered");
        // idle frame: label back to fg2
        let mut v2: Vec<Cmd> = Vec::new();
        scene.draw(
            &mut v2,
            0.0,
            0.0,
            300.0,
            120.0,
            scale(),
            &pal(),
            &hvals,
            0,
            true,
            true,
        );
        let fg2 = ColorToken::Fg2.resolve(&pal());
        assert!(v2.iter().any(|c| matches!(c, Cmd::Text { text, color, .. } if text == "clear mo" && *color == fg2)), "idle clear label is fg2");
    }

    #[test]
    fn news_strip_draws_chips_and_rows_hover_ink() {
        let mut vals = SceneValues::new();
        vals.insert(
            "news_chips",
            SceneValue::Chips(vec![
                "world".into(),
                "tech".into(),
                "science".into(),
                "money".into(),
                "sports".into(),
            ]),
        );
        vals.insert("news_cat_sel", SceneValue::Ring(2.0));
        vals.insert("news_cat_scroll", SceneValue::Ring(40.0));
        vals.insert(
            "news_rows",
            SceneValue::Rows(vec![crate::scene::SceneRow {
                cols: vec![
                    "Big headline here".into(),
                    crate::icons::ICON_OPEN.to_string(),
                    "BBC".into(),
                ],
                key: 0,
                action: None,
                color: None,
                surface: None,
                col_colors: vec![],
            }]),
        );
        vals.insert("news_scroll", SceneValue::Ring(0.0));
        let scene: CardScene = parse_scene_ron(
            "(items: [
                Strip(
                    chips: \"news_chips\",
                    sel: Some(\"news_cat_sel\"),
                    scroll: Some(\"news_cat_scroll\"),
                    x: 0.0, y: 30.0, w: 0.0, h: 26.0,
                    pad: 12.0, spacing: 6.0, chip_pad: 11.0, fs: 8.5,
                    key_base: 13000,
                ),
                Rows(
                    name: \"news_rows\",
                    y: 59.0, row_h: 30.0, pitch: Some(30.0), pad: 12.0, row_dy: 2.0,
                    cols: [
                        (x: 5.0, dy: Some(2.0), size: 9.5, color: Some(fg), hover: Some(acc)),
                        (x: 0.0, edge: Some(12.0), right: true, dy: Some(2.0), size: 8.0, icon: true, color: Some(fg3), hover: Some(acc)),
                        (x: 0.0, edge: Some(12.0), right: true, dy: Some(14.0), size: 7.5, color: Some(fg3)),
                    ],
                    key_base: Some(13300),
                    hairline: true,
                    hover_bar: true,
                ),
             ])",
        )
        .unwrap();
        let acc = ColorToken::Acc.resolve(&pal());
        let sfg = ColorToken::Sfg.resolve(&pal());
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            300.0,
            130.0,
            scale(),
            &pal(),
            &vals,
            13_300,
            true,
            true,
        );
        assert!(
            hits.iter().any(|h| h.key == 13_002),
            "chip index 2 registers a region"
        );
        assert!(
            hits.iter().any(|h| h.key == 13_300),
            "the headline row registers"
        );
        assert!(
            v.iter()
                .any(|c| matches!(c, Cmd::Rect { color, h, .. } if *color == acc && *h == 24.0)),
            "active chip painted accent"
        );
        assert!(
            v.iter().any(
                |c| matches!(c, Cmd::Text { text, color, .. } if text == "science" && *color == sfg)
            ),
            "active chip label in Sfg (accent text)"
        );
        assert!(v.iter().any(|c| matches!(c, Cmd::Rect { color, w, y, .. } if *color == acc && (*w - 2.5).abs() < 0.01 && (*y - 61.0).abs() < 0.02)), "hover accent rail at the row's left");
        let hover_gray = crate::ui::hover(&pal());
        assert!(v.iter().any(|c| matches!(c, Cmd::Rect { color, h, y, .. } if *color == hover_gray && *h == 1.0 && (*y - 88.0).abs() < 0.02)), "hairline divider under the row");
        assert!(v.iter().any(|c| matches!(c, Cmd::Text { text, color, .. } if text == "Big headline here" && *color == acc)), "title tints accent while its row is hovered");
        // idle frame: title back to fg, rail gone
        let mut v2: Vec<Cmd> = Vec::new();
        scene.draw(
            &mut v2,
            0.0,
            0.0,
            300.0,
            130.0,
            scale(),
            &pal(),
            &vals,
            0,
            true,
            true,
        );
        let fg = ColorToken::Fg.resolve(&pal());
        assert!(v2.iter().any(|c| matches!(c, Cmd::Text { text, color, .. } if text == "Big headline here" && *color == fg)), "idle title is fg");
        assert!(!v2.iter().any(|c| matches!(c, Cmd::Rect { color, w, .. } if *color == acc && (*w - 2.5).abs() < 0.01)), "no accent rail without hover");
    }

    #[test]
    fn news_scene_is_fully_declarative() {
        let path = crate::vars::card_scene_path("news");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene =
            parse_scene_ron(&s).unwrap_or_else(|e| panic!("committed news.ron must parse: {e}"));
        assert!(
            scene
                .items
                .iter()
                .all(|i| !matches!(i, SceneItem::Ink { .. })),
            "news scene is fully declarative — no Ink painters"
        );
        let hdr = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Header {
                    title, glyph, meta, ..
                } = i
                {
                    Some((title.clone(), glyph.clone(), meta.clone()))
                } else {
                    None
                }
            })
            .expect("header declared");
        assert_eq!(hdr.0, "News");
        assert_eq!(hdr.1, Some("\u{f1ea}".into()), "news glyph");
        assert!(hdr.2.as_deref().unwrap_or_default().contains("news_label"));
        let strip = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Strip {
                    chips,
                    sel,
                    scroll,
                    y,
                    h,
                    key_base,
                    ..
                } = i
                {
                    Some((
                        chips.clone(),
                        sel.clone(),
                        scroll.clone(),
                        y.clone(),
                        h.clone(),
                        *key_base,
                    ))
                } else {
                    None
                }
            })
            .expect("category strip declared");
        assert_eq!(strip.0, "news_chips");
        assert_eq!(strip.1, Some("news_cat_sel".into()));
        assert_eq!(strip.2, Some("news_cat_scroll".into()));
        assert_eq!(strip.3, Val::Lit(30.0), "strip sits at the header line");
        assert_eq!(strip.4, Val::Lit(26.0));
        assert_eq!(strip.5, crate::shell::NEWS_CAT_KEY_BASE);
        let rows_item = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Rows {
                    name,
                    y,
                    row_h,
                    start,
                    key_base,
                    hairline,
                    hover_bar,
                    cols,
                    ..
                } = i
                {
                    Some((
                        name.clone(),
                        y.clone(),
                        *row_h,
                        start.clone(),
                        *key_base,
                        *hairline,
                        *hover_bar,
                        cols.clone(),
                    ))
                } else {
                    None
                }
            })
            .expect("headline list declared");
        assert_eq!(rows_item.0, "news_rows");
        assert_eq!(rows_item.1, Val::Lit(59.0), "list clears header + strip");
        assert_eq!(rows_item.2, 30.0, "30 px headline pitch");
        assert_eq!(rows_item.3, Some("news_scroll".into()));
        assert_eq!(rows_item.4, Some(crate::shell::NEWS_HEAD_KEY_BASE));
        assert!(rows_item.5, "hairline dividers");
        assert!(rows_item.6, "hover accent rail");
        assert_eq!(rows_item.7.len(), 3);
        assert_eq!(
            rows_item.7[0].hover,
            Some(ColorToken::Acc),
            "title tints accent on hover"
        );
        assert!(rows_item.7[1].icon, "open glyph in the icon font");
        assert!(
            rows_item.7[1].right && rows_item.7[1].edge == Some(12.0),
            "open glyph right-anchored"
        );
        assert_eq!(
            rows_item.7[2].dy,
            Some(14.0),
            "source label below the title"
        );
    }

    #[test]
    fn snippet_flash_draws_translucent_wash_and_flash_ink() {
        let mut vals = SceneValues::new();
        vals.insert(
            "snip_rows",
            SceneValue::Rows(vec![
                crate::scene::SceneRow {
                    cols: vec![
                        crate::icons::ICON_SELECT.to_string(),
                        "ssh".into(),
                        "user@host:22".into(),
                    ],
                    key: 0,
                    action: None,
                    color: None,
                    surface: None,
                    col_colors: vec![],
                },
                crate::scene::SceneRow {
                    cols: vec![
                        crate::icons::ICON_SELECT.to_string(),
                        "addr".into(),
                        "42 Imagination Street".into(),
                    ],
                    key: 0,
                    action: None,
                    color: None,
                    surface: None,
                    col_colors: vec![],
                },
            ]),
        );
        // scalar is index + 1 → row 1 flashes (0 = none)
        vals.insert("snip_flash", SceneValue::Ring(2.0));
        let scene: CardScene = parse_scene_ron(
            "(items: [
                Rows(
                    name: \"snip_rows\",
                    y: 50.0, row_h: 24.0, pad: 12.0, r: 6.0,
                    hover_surface: Some(hover_hl),
                    flash: Some(\"snip_flash\"),
                    cols: [
                        (x: 2.0, dy: Some(4.0), size: 9.0, icon: true, color: Some(fg2), flash: Some(acc)),
                        (x: 18.0, dy: Some(4.0), size: 9.5, color: Some(fg), flash: Some(acc)),
                        (x: 96.0, dy: Some(5.0), size: 8.0, color: Some(fg3)),
                    ],
                    key_base: Some(31710),
                    del_base: 31730,
                    del_pad: 20.0,
                    del_dy: 4.0,
                    del_size: 9.0,
                ),
             ])",
        )
        .unwrap();
        let acc = ColorToken::Acc.resolve(&pal());
        let wash = (pal().acc & 0xFFFF_FF00) | 0x30;
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            300.0,
            130.0,
            scale(),
            &pal(),
            &vals,
            0,
            true,
            true,
        );
        // the flash row (index 1 → ry 74): translucent accent wash behind it
        assert!(v.iter().any(|c| matches!(c, Cmd::Rect { color, y, h, .. } if *color == wash && (*y - 74.0).abs() < 0.02 && *h == 24.0)), "flashed row washed translucent accent");
        // its name inks accent; the preview stays fg3
        assert!(
            v.iter().any(
                |c| matches!(c, Cmd::Text { text, color, .. } if text == "addr" && *color == acc)
            ),
            "flashed name in accent"
        );
        let fg3 = ColorToken::Fg3.resolve(&pal());
        assert!(v.iter().any(|c| matches!(c, Cmd::Text { text, color, .. } if text == "42 Imagination Street" && *color == fg3)), "preview line stays fg3 under the flash");
        // idle row 0: copy glyph fg2, name fg
        let fg2 = ColorToken::Fg2.resolve(&pal());
        assert!(v.iter().any(|c| matches!(c, Cmd::Text { text, color, .. } if text == crate::icons::ICON_SELECT && *color == fg2)), "idle copy glyph stays fg2");
        let fg = ColorToken::Fg.resolve(&pal());
        assert!(
            v.iter().any(
                |c| matches!(c, Cmd::Text { text, color, .. } if text == "ssh" && *color == fg)
            ),
            "idle name stays fg"
        );
        // region: both copy regions registered; ✕ only shows on hover
        assert!(hits.iter().any(|h| h.key == 31_710), "row 0 copy region");
        assert!(hits.iter().any(|h| h.key == 31_711), "row 1 copy region");
        assert!(
            !hits.iter().any(|h| h.key == 31_730),
            "no delete key without hover"
        );
        // hovered + flash: wash beats the hover surface
        let mut v2: Vec<Cmd> = Vec::new();
        scene.draw(
            &mut v2,
            0.0,
            0.0,
            300.0,
            130.0,
            scale(),
            &pal(),
            &vals,
            31_711,
            true,
            true,
        );
        assert!(v2.iter().any(|c| matches!(c, Cmd::Rect { color, y, .. } if *color == wash && (*y - 74.0).abs() < 0.02)), "flash wash beats hover surface");
        // idle (0 = no flash): hover lifts the surface instead
        let mut vals_idle = vals.clone();
        vals_idle.insert("snip_flash", SceneValue::Ring(0.0));
        let mut v3: Vec<Cmd> = Vec::new();
        scene.draw(
            &mut v3,
            0.0,
            0.0,
            300.0,
            130.0,
            scale(),
            &pal(),
            &vals_idle,
            31_711,
            true,
            true,
        );
        let hhl = ColorToken::HoverHl.resolve(&pal());
        assert!(v3.iter().any(|c| matches!(c, Cmd::Rect { color, y, .. } if *color == hhl && (*y - 74.0).abs() < 0.02)), "idle hover surface lifts the row");
        assert!(!v3.iter().any(|c| matches!(c, Cmd::Rect { color, y, .. } if *color == wash && (*y - 74.0).abs() < 0.02)), "no wash without a flash scalar");
    }

