    #[test]
    fn the_alarm_x_reveals_on_hover_and_its_key_turns_it_red() {
        let scene = batt_scene("alarms").expect("scene present");
        let vals = alarm_vals(&[("07:30", "stand up")], None);
        // row hovered: the ✕ appears 26 px from the card's right edge, 4 px
        // into the row, at 9.0 — painted fg until the pointer is on it
        let draw = |hover: u32| {
            let mut v: Vec<Cmd> = Vec::new();
            let (hits, _) = scene.draw(
                &mut v,
                0.0,
                0.0,
                300.0,
                160.0,
                scale(),
                &pal(),
                &vals,
                hover,
                true,
                true,
            );
            (v, hits)
        };
        let x = |v: &[Cmd]| {
            v.iter().find_map(|c| match c {
                Cmd::Text {
                    x, y, size, text, ..
                } if text == crate::icons::ICON_CLOSE => Some((*x, *y, *size)),
                _ => None,
            })
        };
        let (idle, _) = draw(0);
        assert!(x(&idle).is_none(), "no ✕ until the row is hovered");
        let (xv, hits) = draw(31_610);
        assert_eq!(
            x(&xv),
            Some((300.0 - 26.0, 54.0, 9.0)),
            "at the pad + 14, 4 px into the row"
        );
        let del = hits
            .iter()
            .find(|r| r.key == 31_610)
            .expect("the delete region");
        assert_eq!(
            (del.y, del.h),
            (46.0, 22.0),
            "a 22 px target around the glyph"
        );
        let fg = xv
            .iter()
            .find_map(|c| match c {
                Cmd::Text { text, color, .. } if text == crate::icons::ICON_CLOSE => Some(*color),
                _ => None,
            })
            .unwrap();
        assert_eq!(
            fg,
            crate::ui::DANGER,
            "red the moment the pointer is on the ✕ itself"
        );
    }

    #[test]
    fn the_alarm_composer_well_lifts_while_the_input_has_focus() {
        let vals = alarm_vals(&[], Some("09:15"));
        let (v, _) = gau_draw("alarms", 300.0, 160.0, &vals);
        let well = rects(&v)
            .into_iter()
            .find(|r| r.3 == 22.0)
            .expect("the composer well");
        assert_eq!(
            well.4,
            crate::ui::hover_hl(&pal()),
            "the focused well lifts"
        );
        let lbl = texts(&v)
            .into_iter()
            .find(|(_, _, _, s)| s == "09:15")
            .expect("the typed buffer");
        assert_eq!(lbl.0, 20.0, "same inset as the placeholder");
        assert!(
            !texts(&v)
                .iter()
                .any(|(_, _, _, s)| s.starts_with("add alarm")),
            "the placeholder steps aside for the buffer"
        );
        assert!(
            texts(&v).iter().all(|(_, _, _, s)| s != "0 set"),
            "an empty list has no count"
        );
    }

    #[test]
    fn a_full_alarm_list_stops_before_the_card_bottom() {
        // 300x160: rows from y 50, the drawer's cap `floor(((160 - 2) - 50) / 24)` = 4
        let many: Vec<(String, String)> = (0..8)
            .map(|i| (format!("0{i}:00"), format!("alarm {i}")))
            .collect();
        let vals = alarm_vals(
            &many
                .iter()
                .map(|(a, b)| (a.as_str(), b.as_str()))
                .collect::<Vec<_>>(),
            None,
        );
        let (v, _) = gau_draw("alarms", 300.0, 160.0, &vals);
        let tv = texts(&v);
        let drawn: Vec<&String> = tv
            .iter()
            .filter(|(_, _, _, s)| s.starts_with("alarm "))
            .map(|(_, _, _, s)| s)
            .collect();
        assert_eq!(drawn.len(), 4, "four rows clear card_h - 2");
        assert_eq!(
            *drawn.last().unwrap(),
            "alarm 3",
            "the fifth would cross the cap"
        );
    }

    /// quote card (2026-09-27): the whole card went declarative.
    fn quote_vals(state: u8, text: &str, author: &str, saved: usize, flash: u32) -> SceneValues {
        let mut m = SceneValues::new();
        let has = state == 2 && !text.is_empty();
        let p = pal();
        let (meta, ink) = if state == 2 && flash > 0 {
            (
                format!("{} saved", crate::icons::ICON_CHECK),
                SceneColor::Raw(0x2ee6a8ff),
            )
        } else {
            match state {
                1 => ("fetching…".to_string(), SceneColor::Token(ColorToken::Fg3)),
                2 => (format!("{saved} saved"), SceneColor::Token(ColorToken::Fg3)),
                _ => ("—".to_string(), SceneColor::Token(ColorToken::Fg3)),
            }
        };
        m.insert("quote_meta", SceneValue::Text(meta));
        m.insert_color("quote_meta_ink", ink);
        m.insert("quote_text", SceneValue::Text(text.to_string()));
        m.insert("quote_author", SceneValue::Text(author.to_string()));
        m.insert("quote_has", SceneValue::Toggle(has));
        m.insert("quote_fetching", SceneValue::Toggle(state == 1));
        m.insert("quote_empty", SceneValue::Toggle(!has && state != 1));
        m.insert_color("quote_new_fill", SceneColor::Raw(crate::ui::hover_hl(&p)));
        m.insert_color("quote_new_ink", SceneColor::Token(ColorToken::Fg));
        m.insert_color(
            "quote_save_fill",
            SceneColor::Raw(if has {
                0x2ee6a8ff
            } else {
                crate::ui::hover(&p)
            }),
        );
        m.insert_color(
            "quote_save_ink",
            SceneColor::Raw(if has { 0xff141414 } else { crate::ui::fg3(&p) }),
        );
        m
    }

    #[test]
    #[test]
    fn quote_scene_is_zero_ink() {
        if let Some(scene) = batt_scene("quote") {
            assert!(
                !scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ink { .. })),
                "the body + pills are declared"
            );
            assert!(
                scene.items.iter().any(
                    |i| matches!(i, SceneItem::TextWrap { visible: Some(v), .. } if v == "quote_has")
                ),
                "the wrap block is gated on a loaded quote"
            );
        }
    }

    #[test]
    fn the_quote_pill_pair_sits_centered_8px_above_the_bottom() {
        if batt_scene("quote").is_some() {
            let vals = quote_vals(
                2,
                "Simplicity is the ultimate sophistication",
                "Leonardo da Vinci",
                3,
                0,
            );
            let _ = gau_draw("quote", 300.0, 160.0, &vals);
        }
    }
